const fs = require("fs");
const path = require("path");
const os = require("os");
const { execFileSync } = require("child_process");
const html = fs.readFileSync("C:/Users/USER/Downloads/agent-test/harness/runs/subagent_r3/work/index.html", "utf8");
const m = html.match(/<script>([\s\S]*?)<\/script>/);
const out = path.join(os.tmpdir(), "bb_game_check.js");
fs.writeFileSync(out, m[1]);
try {
  execFileSync(process.execPath, ["--check", out], { stdio: "inherit" });
  console.log("SYNTAX_OK");
} finally {
  fs.unlinkSync(out);
}

